#!/bin/bash
# Shared settings for the Kafka toolbox. Sourced by every tool.
REALM="${REALM:-SOLACE.LOCAL}"
BOOTSTRAP="${KAFKA_BOOTSTRAP:-kafka:9093}"
KAFKA_SERVICE_NAME="${KAFKA_SERVICE_NAME:-kafka}"
CLIENT_PRINCIPAL="${CLIENT_PRINCIPAL:-client}"
CLIENT_KEYTAB="${CLIENT_KEYTAB:-/etc/kafka/keytabs/client.keytab}"
export KAFKA_OPTS="${KAFKA_OPTS:--Djava.security.krb5.conf=/etc/krb5/krb5.conf}"

PROPS="${CLIENT_PROPS:-/tmp/client.properties}"

write_client_props() {
  cat > "${PROPS}" <<EOF
# generated by /opt/tools/lib.sh
security.protocol=SASL_PLAINTEXT
sasl.mechanism=GSSAPI
sasl.kerberos.service.name=${KAFKA_SERVICE_NAME}
sasl.jaas.config=com.sun.security.auth.module.Krb5LoginModule required useKeyTab=true storeKey=true keyTab="${CLIENT_KEYTAB}" principal="${CLIENT_PRINCIPAL}@${REALM}";
EOF
}

[ -f "${PROPS}" ] || write_client_props

log() { echo "[kafka-client] $*" >&2; }
